  ('Q4992083', 'Sterling Airways Flight 296', 'On 14 March 1972, Sterling Airways Flight 296 crashed into a mountain ridge on approach to Dubai in Al Hayl, Fujariah. Flight 296 was a charter flight from Colombo to Copenhagen with stops in Bombay, Dubai, and Ankara.', 1972, 3, 14, NULL, NULL, NULL, 'day', '14 March 1972', 52, 'https://en.wikipedia.org/wiki/Sterling_Airways_Flight_296'),
  ('Q1687078', 'Operation Earnest Will', 'Operation Earnest Will (24 July 1987 – 26 September 1988) was an American military protection of Kuwaiti-owned tankers from Iranian attacks in 1987 and 1988, three years into the Tanker War phase of the Iran–Iraq War. It was the largest naval convoy operation since World War II, and flowed from Resolution 598 which had been adopted three days earlier.', 1987, 7, 24, 1988, 9, 26, 'day', '24 July 1987 – 26 September 1988', 52, 'https://en.wikipedia.org/wiki/Operation_Earnest_Will'),
  ('Q2026308', 'Operation Praying Mantis', 'Operation Praying Mantis was the 18 April 1988 attack by the United States on Iranian naval targets in the Persian Gulf in retaliation for the mining of a U.S. warship four days earlier. It took place during the US presidency of Ronald Reagan and the rule of Supreme Leader of Iran Ruhollah Khomeini.', 1988, 4, 18, NULL, NULL, NULL, 'day', '18 April 1988', 57, 'https://en.wikipedia.org/wiki/Operation_Praying_Mantis'),
  ('Q6416483', 'Kish Air Flight 7170', 'Kish Air Flight 7170 was a scheduled international passenger flight from Kish Island in Iran to Sharjah, United Arab Emirates, operated by Iranian airline Kish Air. On February 10, 2004, the aircraft serving the route, a Fokker 50, lost control and crashed onto terrain while on approach to Sharjah International Airport.', 2004, 2, 10, NULL, NULL, NULL, 'day', '10 February 2004', 45, 'https://en.wikipedia.org/wiki/Kish_Air_Flight_7170'),
  ('Q1615396', 'UPS Airlines Flight 6', 'UPS Airlines Flight 6 was a scheduled international cargo flight operated by UPS Airlines. On September 3, 2010, the Boeing 747-400 flying the route between Dubai, United Arab Emirates, and Cologne, Germany, developed an in-flight fire, which caused the aircraft to crash, killing both crew members, the only people on board.', 2010, 9, 3, NULL, NULL, NULL, 'day', '3 September 2010', 57, 'https://en.wikipedia.org/wiki/UPS_Airlines_Flight_6'),
  ('Q26212179', 'Emirates Flight 521', 'Emirates Flight 521 was a scheduled international passenger flight from Thiruvananthapuram, India, to Dubai, United Arab Emirates, operated by Emirates using a Boeing 777. On 3 August 2016, the aircraft, carrying 282 passengers and 18 crew, crashed while landing at Dubai International Airport.', 2016, 8, 3, NULL, NULL, NULL, 'day', '3 August 2016', 64, 'https://en.wikipedia.org/wiki/Emirates_Flight_521'),
  ('Q28716912', 'raid on Yakla', 'The Raid on Yakla was a joint United States/United Arab Emirates military operation carried out on January 29, 2017 in al-Ghayil, a village in the Yakla area of the Al Bayda Governorate of central Yemen, during the Yemeni civil war. Prepared by U.S. counterterrorism officials under President Barack Obama, the mission was ultimately authorized by President Donald Trump nine days into his presidency.', 2017, 1, 29, NULL, NULL, NULL, 'day', '29 January 2017', 37, 'https://en.wikipedia.org/wiki/Raid_on_Yakla'),
  ('Q44407676', 'Battle of Sana''a', 'The Battle of Sanaa in 2017 was fought between forces loyal to Ali Abdullah Saleh and the Houthis in the Yemeni capital of Sanaa. Both sides were allied during the 2014–15 Houthi takeover of the government but the alliance ended when Saleh decided to break ranks with the Houthis and call for dialogue with Saudi Arabia and the United Arab Emirates, who are leading a military intervention in Yemen.', 2017, 11, 29, 2017, 12, 4, 'day', '29 November 2017 – 4 December 2017', 37, 'https://en.wikipedia.org/wiki/Battle_of_Sanaa_(2017)'),
  ('Q48735086', 'Battle of Al Hudaydah', 'The siege of Hodeidah, also called Hudaydah or al-Hudaydah, (Arabic: معركة الحديدة, romanized: Ma‘rakat al-Ḥudaydah), codenamed Operation Golden Victory, was a major Saudi-led coalition assault on the port city of Hodeidah in Yemen. It was spearheaded by the United Arab Emirates and Saudi Arabia and was considered the largest battle since the start of the Saudi Arabian-led intervention in Yemen in 2015.', 2018, 9, 16, NULL, NULL, NULL, 'day', '16 September 2018', 41, 'https://en.wikipedia.org/wiki/Battle_of_Hodeidah'),
  ('Q79401903', 'Riyadh Agreement', 'The Riyadh Agreement (Arabic: اتفاق الرياض, romanized: Ittifāq ar-Riyāḏ) was signed on 5 November 2019 in the capital city of Saudi Arabia, Riyadh, between Abdrabbuh Mansur Hadi, representing the Saudi-backed government of Yemen, Muhammad bin Zayid Al Nahyan, representing the United Arab Emirates, and Aydarus al-Zubaydi, representing the UAE-backed Southern Transitional Council (STC). It followed the Southern Yemen clashes of August 2019, with the goal of ending the fighting and establishing a united front against the Iran-backed Houthi rebels, dominant in the north of the country.', 2019, 11, 5, NULL, NULL, NULL, 'day', '5 November 2019', 34, 'https://en.wikipedia.org/wiki/Riyadh_Agreement'),
